// ─── File: CteDemo.java ───
// Walks an org tree the way WITH RECURSIVE does: anchor + recursive member.
package com.bank.cte;

import java.util.*;
import java.util.logging.*;

public class CteDemo {
    private static final Logger log = Logger.getLogger(CteDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        EmployeeRepository repo = new EmployeeRepository();
        OrgHierarchyService service = new OrgHierarchyService(repo);

        log.info("=== Recursive CTE: full org tree (anchor + recursive member) ===");
        for (Employee e : service.reportingTree()) {
            String indent = "  ".repeat(e.level - 1);
            log.info(() -> "lvl" + e.level + " " + indent + e.name + " (" + e.empId + ")");
        }
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    final String empId, name, managerId; // managerId null for top
    int level; // populated during traversal (the CTE's lvl column)
    Employee(String id, String name, String mgr) {
            this.empId = id;
            this.name = name
            this.managerId = mgr;
    }
    Employee withLevel(int lvl) {
        Employee copy = new Employee(empId, name, managerId);
        copy.level = lvl; return copy;
    }
}

// ─── Would be in repository/EmployeeRepository.java ───
class EmployeeRepository {
    List<Employee> findAll() {
        return List.of(
            new Employee("E1", "Rajesh Kumar", null),
            new Employee("E2", "Priya Sharma", "E1"),
            new Employee("E3", "Amit Verma",   "E1"),
            new Employee("E4", "Neha Gupta",   "E2"));
    }
}

// ─── Would be in service/OrgHierarchyService.java ───
class OrgHierarchyService {
    private final EmployeeRepository repo;
    OrgHierarchyService(EmployeeRepository repo) { this.repo = repo; }

    // Mirrors WITH RECURSIVE: anchor (manager_id IS NULL), then iterate reports.
    List<Employee> reportingTree() {
        List<Employee> all = repo.findAll();
        List<Employee> result = new ArrayList<>();

        // ANCHOR member: the top manager (manager_id IS NULL), level 1
        List<Employee> frontier = new ArrayList<>();
        for (Employee e : all)
            if (e.managerId == null) frontier.add(e.withLevel(1));
        result.addAll(frontier);

        // RECURSIVE member: repeat until no new rows produced
        while (!frontier.isEmpty()) {
            List<Employee> next = new ArrayList<>();
            for (Employee parent : frontier) {
                for (Employee e : all) {
                    if (parent.empId.equals(e.managerId)) {   // e.manager_id = org.emp_id
                        next.add(e.withLevel(parent.level + 1)); // o.lvl + 1
                    }
                }
            }
            result.addAll(next);     // UNION ALL accumulation
            frontier = next;         // feed new rows back in
        }
        return result;
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
